# Now implement the pattern logic
output = [row[:] for row in test_input]

for i, row in enumerate(test_input):
    first_idx = None
    for j, val in enumerate(row):
        if val != 9:  # 9 is background, look for 8s
            first_idx = j
            break

    if first_idx is not None:
        for j in range(first_idx, 15):
            dist = j - first_idx
            if dist % 2 == 1:  # odd distance from first 8
                # Replace background at odd positions with 2
                if output[i][j] == 9:
                    output[i][j] = 2

# Print the result
for i, row in enumerate(output):
    print(f"Row {i}: {row}")

